    if (timerRef.current) clearTimeout(timerRef.current);
    timerRef.current = setTimeout(() => setToastOpen(false), 4000);
  }

  return (
    <div className="jx-stack">
      <form className="jx-field-group" onSubmit={handleSubmit}>
        <label className="jx-label" htmlFor="newsletter-email">
